    try {
      const customers = Object.values(customerDb || {});
      if (customers.length === 0) {
        toast.info("No customers to export.");
        return;
      }

      const headers = ['name', 'phone', 'address', 'orders', 'totalSpent', 'balance', 'points'];

      const csvRows = [
        headers.join(','),
        ...customers.map(c => {
          return headers.map(header => {
            let val = c[header] !== undefined ? c[header] : '';
